    System.out.println(JsonUtils.toJson(result));
  }
}

curl -X POST https://dashscope.aliyuncs.com/api/v1/services/aigc/text2image/image-synthesis \
  -H 'X-DashScope-Async: enable' \
  -H "Authorization: Bearer $DASHSCOPE_API_KEY" \
  -H 'Content-Type: application/json' \
  -d '{
  "model": "qwen-image-plus",
  "input": {
    "prompt": "Healing-style hand-drawn poster featuring three puppies playing with a ball on lush green grass."
  },
  "parameters": {
    "negative_prompt": "",
    "size": "1664*928",
    "n": 1,
    "prompt_extend": true,
    "watermark": false
  }
}'

import com.alibaba.dashscope.aigc.imagesynthesis.ImageSynthesis;
import com.alibaba.dashscope.aigc.imagesynthesis.ImageSynthesisParam;
import com.alibaba.dashscope.aigc.imagesynthesis.ImageSynthesisResult;
import com.alibaba.dashscope.utils.Constants;
import com.alibaba.dashscope.utils.JsonUtils;

import java.util.HashMap;
import java.util.Map;

public class QwenImageAsync {
  static {
    Constants.baseHttpApiUrl = "https://dashscope.aliyuncs.com/api/v1";
  }

  static String apiKey = System.getenv("DASHSCOPE_API_KEY");

  public static void main(String[] args) throws Exception {
    String prompt = "Healing-style hand-drawn poster featuring three puppies "
      + "playing with a ball on lush green grass. The main title "
      + "'Come Play Ball!' is prominently displayed at the top.";

    Map<String, Object> parameters = new HashMap<>();
    parameters.put("prompt_extend", true);
    parameters.put("watermark", false);
    parameters.put("negative_prompt", "");

    ImageSynthesisParam param = ImageSynthesisParam.builder()
      .apiKey(apiKey)
      .model("qwen-image-plus")
      .prompt(prompt)
      .n(1)
      .size("1664*928")
      .parameters(parameters)
      .build();

    ImageSynthesis imageSynthesis = new ImageSynthesis();
    System.out.println("---正在调用接口，请等待任务完成。----");
    ImageSynthesisResult result = imageSynthesis.call(param);
    System.out.println(JsonUtils.toJson(result));
  }
}
